import{_ as a}from"./chunks/Fill_L1.hzlHj2RI.js";import{_ as n,o as t,a as l,b as p}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/Fill_L0A.CrJ2FW7N.png",b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬入辅助配置接口","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/cube_load_aux_config"},{"text":"Fill","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/Fill"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/Fill.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/Fill.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788436684000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/Fill.md"};function c(d,s,r,o,u,_){return t(),l("div",null,[...s[0]||(s[0]=[p('<div><article class="markdown-body"><h1>Fill<span id="ZH-CN_TOPIC_0000001834660669"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>将特定物理存储位置的LocalTensor初始化为某一具体数值。仅支持L1 Buffer/L0A Buffer/L0B Buffer上的LocalTensor初始化。</p><p>如下图所示，将数据空间内最后三行初始化为0，配置InitConstValueParams参数：initValue=0表示初始化值为0，repeatTimes=5表示按照行方向迭代5次，blockNum=3表示每次repeat对列方向的3块32Byte数据块清0，dstGap=5表示相邻repeat之间间隔5个数据块。</p><p><strong>图1</strong> L1 Buffer中Fill示意图<span id="zh-cn_topic_0000002512331632_fig197511640134513"></span><br><img src="'+a+'" alt title="L1 Buffer中Fill示意图"></p><p>如下图所示，将内存空间内的值全部初始化为0，需要配置InitConstValueParams参数：initValue=0表示初始化值为0，repeatTimes=5表示按照行方向迭代5次，blockNum=2表示每次repeat对列方向的2块512Byte数据块清0，dstGap=3表示相邻repeat之间间隔3个数据块。</p><p><strong>图2</strong> L0A Buffer中Fill示意图<span id="zh-cn_topic_0000002512331632_fig11499125816478"></span><br><img src="'+i+`" alt></p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">PrimT</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Std</span><span class="o">::</span><span class="n">enable_if</span><span class="o">&lt;</span><span class="n">Std</span><span class="o">::</span><span class="n">is_same</span><span class="o">&lt;</span><span class="n">PrimT</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">U</span><span class="o">&gt;::</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="o">&gt;::</span><span class="n">type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Fill</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">InitConstValueParams</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">initConstValueParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名称</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst的数据类型。</td></tr><tr><td>U</td><td>初始化值的数据类型。<br>  •当dst使用基础数据类型时，U和dst的数据类型T需保持一致，否则编译失败。<br>  •当dst使用<a href="../../aux_data_structures/TensorTrait/TensorTrait.html">TensorTrait</a>类型时，U和dst的数据类型T的LiteType需保持一致，否则编译失败。<br>  最后一个模板参数仅用于上述数据类型检查，用户无需关注。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，结果矩阵，类型为LocalTensor。</td></tr><tr><td>InitConstValueParams</td><td>输入</td><td>初始化相关参数，类型为InitConstValueParams。<br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。<br>参数说明请参考<a href="#table3">表3</a>。</td></tr></tbody></table><p><span id="table3"></span><strong>表3</strong> InitConstValueParams结构体参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>repeatTimes</td><td>迭代次数。默认值为0。取值范围：repeatTimes∈[0, 32767]。<strong>注：repeatTimes = 0表示不执行，该指令将被视为NOP（空操作）。</strong></td></tr><tr><td>blockNum</td><td>每次迭代初始化的数据块个数，取值范围：blockNum∈[0, 32767]。默认值为0。<strong>注：blockNum = 0表示不执行，该指令将被视为NOP（空操作）。</strong><br>  • dst的物理存储位置为L1 Buffer（TPosition: A1/B1）时，每一个block（数据块）大小是32B；<br>  • dst的物理存储位置为L0A Buffer（TPosition: A2）/L0B Buffer（TPosition: B2）时，每一个block（数据块）大小是512B。</td></tr><tr><td>dstGap</td><td>目的操作数前一个迭代结束地址到后一个迭代起始地址之间的距离。<br>  • dst的物理存储位置为L1 Buffer（TPosition: A1/B1）时，单位是32B；<br>  • dst的物理存储位置为L0A Buffer（TPosition: A2）/L0B Buffer（TPosition: B2）时，单位是512B。<br>  取值范围：dstGap∈[0, 32767]。默认值为0。</td></tr><tr><td>initValue</td><td>初始化的value值，支持的数据类型与dst保持一致。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="910">Atlas 训练系列产品，支持的数据类型为：half。</div><br><div data-filter="310p">Atlas 推理系列产品AI Core，支持的数据类型为：int16_t、uint16_t、half。</div><br><div data-filter="910b">Atlas A2训练系列产品/Atlas A2推理系列产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</div><br><div data-filter="A3">Atlas A3训练系列产品/Atlas A3推理系列产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</div><br><div data-filter="310b">Atlas 200I/500 A2 推理产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</div><br><div data-filter="950">Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</div><br><div data-filter="x90">Kirin X90，支持的数据类型为：int8_t、half。</div><br><div data-filter="9030">Kirin 9030，支持的数据类型为：half。</div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>当目的操作数位于L0A Buffer/L0B Buffer时，指令执行占用的流水为PIPE_MTE1，目的操作数地址需要512Byte对齐。当目的操作数位于L1 Buffer时，指令执行占用的流水为PIPE_MTE2，目的地址需要32Byte对齐。</p></li><li><p>当repeatTimes为0或者blockNum为0时，指令不会进行任何操作。</p></li><li><p>不同的型号在设置InitConstValueParams参数时，支持配置参数的不同。</p><ul><li>仅支持配置迭代次数和初始化值场景下，其他参数配置无效。每次迭代处理固定数据量（512字节），迭代间无间隔。</li><li>支持配置所有参数场景下，支持配置迭代次数、初始化值、每个迭代处理的数据块个数和迭代间间隔。</li></ul><div data-filter="910,310p"><ul><li><p>特别地，针对如下型号，仅支持配置迭代次数和初始化值。</p><div data-filter="910"><ul><li>Atlas 训练系列产品。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core。</li></ul></div></li></ul></div></li><li><p>支持的物理存储位置为：L1 Buffer（TPosition: A1/B1）、L0A Buffer（TPosition: A2）、L0B Buffer（TPosition: B2）。</p><div data-filter="950"><ul><li>特别针对Ascend 950PR/Ascend 950DT，支持物理存储位置为：L1 Buffer（TPosition: A1/B1）。</li></ul></div><ul><li>如果物理存储位置为L1 Buffer（TPosition: A1/B1），起始地址需要满足32B对齐；</li><li>如果物理存储位置为L0A Buffer（TPosition: A2）、L0B Buffer（TPosition: B2），起始地址需要满足512B对齐。</li></ul></li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">mLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">kLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="n">Fill</span><span class="p">(</span><span class="n">leftMatrix</span><span class="p">,</span><span class="w"> </span><span class="p">{</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">kLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">32</span><span class="p">),</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">});</span><span class="w"> </span><span class="c1">// 给leftMatrix填充mLength * kLength长度的数据为1，按32B的颗粒度进行填充</span>
</code></pre></div><p>若接口用于对L1 Buffer/L0A Buffer/L0B Buffer上的LocalTensor清0使用，示例请参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/06_compatibility_guide/fill">Fill调用样例</a>。</p></article></div>`,1)])])}const A=n(e,[["render",c]]);export{b as __pageData,A as default};
